import 'dart:io';

import 'package:flutter/services.dart';

import '../models/grades.dart';
import 'auth_service.dart';
import 'exceptions.dart';

enum DocumentResult { opened, noViewer, unavailable, failed }

/// Downloads LSF documents and hands them to the system's PDF viewer or
/// share sheet.
///
/// Files go to the app's cache (`documents/`), never to shared storage:
/// they are personal and are re-generated by LSF on every request anyway.
class DocumentService {
  DocumentService(this._auth);

  static const MethodChannel _channel =
      MethodChannel('org.mercul.uniwe/documents');

  final AuthService _auth;

  /// Downloads [document] and opens it ([share] = false) or offers it to
  /// other apps ([share] = true).
  Future<DocumentResult> handOver(LsfDocument document,
      {bool share = false}) async {
    final File file;
    try {
      final bytes = await _auth.downloadDocument(document);
      final dir = await _channel.invokeMethod<String>('directory');
      if (dir == null) return DocumentResult.failed;
      file = File('$dir/${fileName(document.title)}');
      await file.writeAsBytes(bytes, flush: true);
    } on DocumentUnavailableException {
      return DocumentResult.unavailable;
    } catch (_) {
      return DocumentResult.failed;
    }

    try {
      final handled = await _channel.invokeMethod<bool>(
        share ? 'share' : 'open',
        {'path': file.path, 'mimeType': 'application/pdf'},
      );
      return handled == true ? DocumentResult.opened : DocumentResult.noViewer;
    } on PlatformException {
      return DocumentResult.failed;
    } on MissingPluginException {
      return DocumentResult.failed;
    }
  }

  /// A file name from a document title, e.g. "Grade Transcript" →
  /// "Grade_Transcript.pdf". Keeps letters (including umlauts) and digits.
  static String fileName(String title) {
    final base = title
        .replaceAll(RegExp(r'[^\p{L}\p{N}]+', unicode: true), '_')
        .replaceAll(RegExp(r'^_+|_+$'), '');
    final short = base.length > 60 ? base.substring(0, 60) : base;
    return '${short.isEmpty ? 'document' : short}.pdf';
  }
}
